  insert into public.brands (name, website, description, country, status) values ('Bloomeffects', 'https://bloomeffects.com', 'Amsterdam-branded skincare label built around a Proprietary Tulip Complex made from upcycled tulips from its own farm, selling serums, moisturizers, cleansers and SPF — including the Royal Tulip Moisturizing Nectar and Black Tulip Regenerative Brightening Serum — through its own online store; an Allure Best of Beauty Award winner (2024).', 'Netherlands', 'published') returning id into bid;
