  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bloom Collective affiliate program', 'https://bloomeffects.com/pages/affiliate', 'https://bloomeffects.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bloomeffects.com/pages/affiliate', 'official_site', 'affiliate', 'Bloomeffects'' own affiliate page (''Join the Bloom Collective'') publishes the program terms: a minimum 15% commission on full-price products and 7% on discounted or sale items, earned via a unique promo code (excluding gift cards and kits), free to join, with gratis/gifting opportunities, exclusive discount codes for the affiliate''s community and a dedicated HQ support team. No earnings-cap statement is published, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bloomeffects.com', 'official_site', 'general', 'The brand''s homepage (''Tulip Skincare & Botanical Beauty - Bloomeffects Amsterdam'') describes skincare built on a Proprietary Tulip Complex from upcycled farm tulips, shows an Allure Best of Beauty Award Winner 2024 badge and press logos including Vogue, Elle and Marie Claire, and offers free US shipping on orders over $50.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bloomeffects.com/pages/affiliate', 'official_site', 'ugc_collab', 'The affiliate page''s join steps tell affiliates to follow the brand on Instagram and TikTok @bloomeffects and to create content and share product recommendations using the hashtag #bloomeffectspartner — an explicit creator-content program.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 14, 10, 8, 4, '{"compensation": "Published on the brand''s own page: minimum 15% commission on full-price products (7% on sale items) via a unique promo code, plus gratis and gifting \u2014 a solid, transparent rate, though no cap statement is published so the cap stays unknown.", "contact_access": "A public application route on the brand''s own affiliate page with a dedicated HQ affiliate team, but no published partnerships email.", "credibility": "Award-winning brand (Allure Best of Beauty 2024) with major press coverage (Vogue, Elle, Marie Claire) and its own established DTC storefront.", "niche_fit": "Pure skincare with highly demonstrable serums, moisturizers and SPF \u2014 a core skincare-creator niche.", "opportunity_availability": "Free to join via the application on the brand''s own page, followed by a team induction \u2014 open but application-based.", "ugc_evidence": "The program is explicitly built around creator content: affiliates are instructed to post recommendations with the #bloomeffectspartner hashtag and can receive gratis product."}'::jsonb);
