  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/purlisse', 'listing', 'affiliate', 'Rateful''s TikTok Shop data page for pūrlisse reports affiliate creators drove about 20% of the brand''s estimated $2.1K in TikTok Shop sales in the 30 days to Nov 3, 2026 (99 items, 49 products on sale), confirming an active TikTok Shop affiliate program that creators with TikTok Shop affiliate access can join by adding products to their showcase. TikTok Shop does not publish the brand''s commission rate here, and third-party listings for Purlisse''s other affiliate routes conflict (15% vs 20%), so the rate is recorded as null; no earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
