  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 5, 4, 8, 3, '{"compensation": "No verified published rate: TikTok Shop terms are not public and third-party listings for the brand''s other routes conflict (15% vs 20%), so the rate is null and compensation stays low.", "contact_access": "No public partnerships email or application page was found on the pages fetched; joining runs through TikTok Shop''s affiliate center.", "credibility": "Long-running niche skincare brand with its own storefront, but TikTok Shop sales volume is small (about $2.1K estimated in 30 days).", "niche_fit": "Pure skincare (masks, serums, cleansers) \u2014 a core skincare-creator niche with demonstrable products.", "opportunity_availability": "Open to any creator with TikTok Shop affiliate access via the brand''s TikTok Shop storefront.", "ugc_evidence": "Affiliate creators demonstrably sell this brand on TikTok Shop (about 20% of its shop sales), though the brand runs no public creator program page of its own."}'::jsonb);
