  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mented Affiliate Programs (Brand Affiliate, TikTok Affiliate, Amazon Associates)', 'https://mentedcosmetics.com/pages/mented-affiliate-programs', 'https://mentedcosmetics.com/pages/mented-affiliate-programs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mentedcosmetics.com/pages/mented-affiliate-programs', 'official_site', 'affiliate', 'Mented''s own affiliate programs page describes three creator routes: a Brand Affiliate Program (via GrowthHero) offering free products, early launch access and social campaign collaborations; a TikTok Affiliate route where creators sign up through TikTok Shop and ''earn commissions on every sale generated through your affiliate links or tagged videos'' (TikTok eligibility: at least 1,000 followers); and Amazon Associates links for its Amazon listings. No commission rates are published on the page, so the rate is recorded as null; no earnings-cap statement is published, so the cap is unknown.', 'verified', now());
