  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 5, 10, 8, 3, '{"compensation": "Commission routes exist (TikTok Shop and Amazon Associates) but the brand publishes no rates on its program page, so the rate is null and compensation stays low.", "contact_access": "A public affiliate programs page on the brand''s own site with sign-up routes for all three programs, but no published partnerships email.", "credibility": "Smaller independent beauty brand with its own storefront and multi-channel affiliate infrastructure; no major retail footprint was evidenced on the pages fetched.", "niche_fit": "Inclusive makeup is a core beauty-creator niche, with tutorials and reviews named as the brand''s affiliate content formats.", "opportunity_availability": "Three open routes on one public page; the TikTok route requires meeting TikTok''s eligibility (1,000+ followers).", "ugc_evidence": "A dedicated, creator-facing affiliate page on the official site with defined content formats and a feature opportunity on brand channels."}'::jsonb);
