  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/83363', 'affiliate_network', 'affiliate', 'Red Apple Lipstick''s Awin merchant profile runs an open affiliate program aimed at creators and micro-creators (''Whether you''re a TikToker with 1K followers, an Instagram storyteller... our program is designed for you''), citing 4.9/5-star products and a $54 AOV; the profile itself publishes no commission rate and no earnings-cap statement, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkmydeals.com/affiliate-programs/info/redapplelipstick.com/', 'affiliate_network', 'affiliate', 'LinkMyDeals'' affiliate program listing for redapplelipstick.com lists its Awin campaign at a sale commission of 10%, consistent with an older (2020) affiliate roundup that also listed the Red Apple Lipstick program at 10% with a 30-day cookie — no conflicting rate was found, so 10% is recorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://redapplelipstick.com', 'official_site', 'general', 'The brand''s homepage describes clean makeup that is gluten-free, certified cruelty-free, vegan and made for sensitive skin, ''Made in the USA in small batches'', with 4.8 stars from 54,000+ customers and 15 years of helping people with sensitivities wear makeup.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 11, 6, 8, 4, '{"compensation": "A 10% sale commission on Awin is reported by the network listing and an older roundup with no conflicting figure \u2014 mid-range and reasonably corroborated, though not published on the profile itself.", "contact_access": "No public partnerships email was found on the pages fetched; contact runs through the Awin program.", "credibility": "15-year-old brand with 54,000+ customers and 4.8-star ratings per its own homepage, selling DTC with a managed network program.", "niche_fit": "Clean, allergen-friendly makeup for sensitive skin is a defined beauty niche with a loyal creator community, narrower than mainstream makeup.", "opportunity_availability": "Open application through Awin, explicitly welcoming micro-creators with quick approvals per the profile.", "ugc_evidence": "The Awin profile is written to TikTokers, Instagram storytellers and YouTubers and promotes micro-creator participation, though the brand has no creator page of its own."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Avène', 'https://www.aveneusa.com', 'Sensitive-skin skincare brand built around Avène Thermal Spring Water — cleansers, moisturizers, serums and care for eczema-prone, redness-prone, dehydrated and post-procedure skin — sold through its US online store, aveneusa.com.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkwhisper.com/skincare-affiliate-programs/.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkwhisper.com/skincare-affiliate-programs/', 'listing', 'affiliate', 'LinkWhisper''s skincare affiliate programs guide states the Avène affiliate program is run through Rakuten, gives affiliates custom offers, tracking tools, account management and creative materials, and notes commission details aren''t made public — so the rate is recorded as null. No earnings-cap statement is published, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.aveneusa.com', 'official_site', 'general', 'Avène USA''s homepage sells a full sensitive-skin range organized by concern (skin barrier, hypersensitive, eczema-prone, redness-prone, post-procedure, acne-prone) around its Thermal Spring Water, with dermatologist-recommended products such as Cicalfate+ Restorative Protective Cream ($26-$40).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 9, 5, 4, 7, 5, '{"compensation": "A live Rakuten program exists but the commission is not public, so the rate is null and compensation stays low until confirmed in-network.", "contact_access": "No public partnerships email or application page was found on the pages fetched; contact runs through the Rakuten program.", "credibility": "Major dermatologist-recommended skincare brand with a full US storefront and clinically positioned product lines.", "niche_fit": "Sensitive-skin skincare is a core skincare-creator niche with highly demonstrable, problem-led products.", "opportunity_availability": "Application through Rakuten Advertising, subject to advertiser approval.", "ugc_evidence": "The program offers creators custom offers and creative materials per the guide, but Av\u00e8ne publishes no dedicated creator or ambassador page of its own."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tinggly', 'https://tinggly.com', 'Experience-gifting company founded in 2014 and headquartered in Vilnius, Lithuania, selling gift boxes and vouchers redeemable for experiences (adventures, spa days, food tours, getaways) in more than 100 countries.', 'Lithuania', 'published') returning id into bid;
