  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://tinggly.com/affiliate-program.', 'https://tinggly.com/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tinggly Affiliate Program (Impact) — tiered 5%/10%/15%', 'https://tinggly.com/affiliate-program', 'https://tinggly.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tinggly.com/affiliate-program', 'official_site', 'affiliate', 'Tinggly''s official affiliate page states the program runs on Impact Radius (ID 23213) with tiered commission: 1-3 sales/month pays 5%, 4-11 sales/month pays 10%, and 12+ sales/month pays 15%. Signup is instant and free, no website is required (social channels including YouTube, Instagram and TikTok are accepted), and the page states ''More than 400 people have joined our affiliate network.'' No earnings-cap statement appears on the page, so the cap is recorded as unknown; 400+ joined is a few hundred, so saturation is unknown rather than low.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.eu-startups.com/directory/tinggly/', 'listing', 'general', 'EU-Startups'' directory profile states Tinggly was founded in 2014 by Linas Ceikus and Alex Gibb and is headquartered in Vilnius, Lithuania, as a global experience gifting company within the Tinggly Group of European experience gift companies.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 15, 12, 9, 5, '{"compensation": "Published tiered commission on the brand''s own page reaching 15% at 12+ sales/month \u2014 solid, transparent pay for the travel niche.", "contact_access": "A dedicated affiliate page with instant Impact signup and a named program route; the page''s contact email was masked in the fetched copy, so no email is recorded.", "credibility": "Founded 2014, headquartered in Vilnius, part of a European experience-gift group with 300+ employees per EU-Startups.", "niche_fit": "Experience gifts are highly demonstrable in travel and gifting content, and the brand explicitly welcomes social-first promoters.", "opportunity_availability": "Open, instant, free signup on Impact with no website requirement.", "ugc_evidence": "The official page confirms an active affiliate network of 400+ promoters and names YouTube, Instagram and TikTok as accepted promotion channels, though no formal UGC/ambassador program is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tripaneer', 'https://www.tripaneer.com', 'Amsterdam-based travel platform (Tripaneer B.V.) for themed holidays — yoga and meditation retreats, surf camps, wellness, martial arts and culinary trips worldwide, with trip prices roughly from $100 to $10,000.', 'Netherlands', 'published') returning id into bid;
