  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program (in-house)', 35, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://tripaneer.zendesk.com/hc/en-us/articles/360006548860-Commission-Share.', 'https://www.bookyogaretreats.com/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tripaneer Affiliate Program — 35-50% share of booking commission', 'https://www.bookyogaretreats.com/affiliates', 'https://tripaneer.zendesk.com/hc/en-us/articles/360006548860-Commission-Share', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tripaneer.zendesk.com/hc/en-us/articles/360006548860-Commission-Share', 'official_site', 'affiliate', 'Tripaneer''s official help page documents its in-house affiliate commission share: affiliates receive a share of the commission Tripaneer itself earns on a booking — 35% of that commission at 0-50 bookings/month, 40% at 51-100, 45% at 101-250 and 50% at 250+. Tripaneer states it receives 10-20% commission on bookings on average, and inquiries carry a 14-day cookie. The recorded 35 is the entry-tier share of Tripaneer''s commission, not a percentage of the booking price. No earnings-cap statement was found, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bookyogaretreats.com/affiliates', 'official_site', 'compensation', 'Tripaneer''s affiliate agreement (referenced from its BookYogaRetreats affiliate page) provides monthly payout by bank transfer or PayPal with a €100 minimum payout threshold.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 13, 10, 8, 4, '{"compensation": "Published revenue-share tiers (35% rising to 50% of Tripaneer''s 10-20% booking commission, i.e. roughly 3.5-10% of booking value) \u2014 transparent terms, mid-range effective rate.", "contact_access": "A public affiliate signup route exists via its retreat brands'' affiliate pages, with terms documented in the official help center.", "credibility": "Established Amsterdam-based platform (Tripaneer B.V.) operating multiple themed-travel brands.", "niche_fit": "Retreats, surf camps and wellness trips are strong travel-creator content categories with high order values.", "opportunity_availability": "Open affiliate application; no follower threshold published.", "ugc_evidence": "A documented in-house affiliate program exists, but no published ambassador/UGC program or creator community was found."}'::jsonb);
