  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'loveholidays Affiliate and Partnerships Programme (Partnerize)', 'https://www.loveholidays.com/about-us/affiliate.html', 'https://www.loveholidays.com/about-us/affiliate.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.loveholidays.com/about-us/affiliate.html', 'official_site', 'affiliate', 'loveholidays'' official affiliate page states the programme is managed on Partnerize, pays commission only on consumed bookings (paid within 60 days of the departure date, last-click attribution), and is open to all publishers except adult content sites. The page publishes no commission rate and no earnings-cap statement, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/loveholidays-affiliate-program/', 'listing', 'compensation', 'Travelpayouts'' partner-program guide reports loveholidays pays 4% commission of the order cost on consumed bookings, with payout within 90 days after checkout at the time of writing.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/loveholidays-com-affiliate-program', 'listing', 'compensation', 'Shopper''s partnership listing reports a higher payout of up to 6% per sale, which conflicts with the 4% reported by Travelpayouts and Creator Hero; the 4% figure is recorded as the corroborated rate and the 6% figure is flagged here.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 10, 12, 9, 5, '{"compensation": "4% of order cost on consumed bookings is corroborated by two independent sources; a 6% outlier is flagged in evidence.", "contact_access": "A dedicated official affiliate page with clear joining instructions via Partnerize signup.", "credibility": "One of the UK''s largest online travel agents, rated 4.4/5 from 288,169 Trustpilot reviews per its own page.", "niche_fit": "Package holidays and deals are staple travel-creator content, with high booking values offsetting a modest percentage.", "opportunity_availability": "Open to all publishers (except adult sites) through Partnerize registration.", "ugc_evidence": "An open publisher programme with a committed affiliate team per the official page, but no creator/ambassador program is published."}'::jsonb);
