  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'eDreams Affiliate Program (Awin) — 2-6% by product', 'https://ui.awin.com/merchant-profile/6587', 'https://ui.awin.com/merchant-profile/6587', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/6587', 'affiliate_network', 'affiliate', 'eDreams'' official Awin merchant profile (eDreams US) publishes a product-based commission schedule instead of a single rate: Flights 2%, Flights+Prime 3%, Flight+hotel 2%, Flight+hotel+Prime 3%, Hotel 2%, Hotel+Prime 6% and Car hire 6%, on a 30-day cookie. Because no single rate applies, commission_rate is null and the schedule is documented here. No earnings-cap statement appears, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 8, 8, 10, 8, 5, '{"compensation": "Published Awin schedule of 2-6% depending on product \u2014 real but low, and no single headline rate exists.", "contact_access": "Joinable through the official Awin merchant profile; no direct creator contact is published.", "credibility": "eDreams ODIGEO is one of the world''s largest online travel groups and a publicly listed Spanish company.", "niche_fit": "Flights and hotels are core travel content, though a large OTA is a less distinctive creator partner than a niche brand.", "opportunity_availability": "Open application through Awin.", "ugc_evidence": "A standard network affiliate program only; no creator or ambassador program is published."}'::jsonb);
