  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/nomad-lane/', 'affiliate_network', 'affiliate', 'LinkClicky''s affiliate directory (last updated March 11, 2024) lists Nomad Lane''s affiliate program on ShareASale paying a flat $5 per sale (not a percentage) with a 15-day cookie, open to all regions. The flat bounty is documented here and commission_rate is null. No earnings-cap statement was found, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://leadiq.com/c/nomad-lane/5b6c61a435000021e2a29039', 'listing', 'general', 'LeadIQ''s company profile describes Nomad Lane as a New York-based retailer founded in 2017 by Kish and Vanessa Jeswani, designing travel bags and accessories, with the Bento Bag raising over $2M in crowdfunding pre-orders and coverage in Forbes and Travel + Leisure.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 8, 6, 7, 7, 3, '{"compensation": "A flat $5 per sale on premium-priced bags is low versus percentage programs, and the listing dates from March 2024.", "contact_access": "No affiliate page or contact is published on the brand''s own site; the only route is the ShareASale listing in the directory.", "credibility": "Small independent brand (2-10 employees per LeadIQ) with strong crowdfunding history and national press coverage.", "niche_fit": "Premium travel bags are a natural fit for packing and travel-gear content, though the catalog is narrow.", "opportunity_availability": "Joinable via ShareASale per the directory listing, but not promoted on the brand''s own site.", "ugc_evidence": "Only a network affiliate listing was found; no creator program, ambassador page or UGC evidence is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lane Boots', 'https://www.laneboots.com', 'Texas-rooted footwear brand founded in 2007 making designer-quality, handcrafted leather western boots for women (and men), bench-made by artisans in its own factory in León, Mexico since 2013, with its signature turquoise soles; average listed product price is about $311.', 'United States', 'published') returning id into bid;
