  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://snow-consulting.com/category/affiliate-programs/lane-boots', 'affiliate_network', 'affiliate', 'Snow Consulting, the agency that manages the program, announced the Lane Boots affiliate program on ShareASale and invites affiliates to join — corroborating the network and that the program is actively managed.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/lane-boots-preferred/', 'listing', 'compensation', 'Lasso''s ''Lane Boots Preferred'' listing reports a 6%-18% per sale range with a 15-day cookie, and Shopper reports 5-10%, while an older Mopubi listing reported 15%. Because the reported rates conflict, commission_rate is null and the range is documented here. No earnings-cap statement was found, so the cap is unknown.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bootcollector.net/profiles/lane-boots/', 'listing', 'general', 'Boot Collector''s brand profile states Lane Boots launched in 2007 with Texas roots, makes its boots in León, Mexico, and has run its own dedicated factory there since late 2013, expanding from boots into booties, mules, loafers, accessories and apparel.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 12, 8, 8, 4, '{"compensation": "Published rates are strong at the top end (18% per LinkClicky; Lasso reports a 6-18% range) but conflict across sources, so no single rate is recorded.", "contact_access": "No affiliate page or creator contact is published on the brand''s own site; joining runs through ShareASale.", "credibility": "Founded 2007, operates its own factory, estimated $10-25M annual revenue per LeadIQ \u2014 an established independent brand.", "niche_fit": "Designer western boots are a distinctive, demonstrable fashion niche with premium prices (about $311 average) that suit outfit and styling content.", "opportunity_availability": "Open application via ShareASale per the directory and the program''s managing agency.", "ugc_evidence": "An actively managed ShareASale program plus an influencer-program listing exist, but no ambassador or UGC program is published on the brand''s own site."}'::jsonb);
