  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/6343', 'affiliate_network', 'affiliate', 'Public Desire''s official Awin merchant profile states a default commission of 8% on all sales with up to 15% commission available, a 30-day cookie, commission calculated excluding VAT and P&P, and commissions validated over 30 days; the program is managed by Conversion Digital. No earnings-cap statement appears, so the cap is unknown.', 'publicly_reported', now());
