  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tillys Affiliate Program (Impact)', 'https://www.tillys.com/about-tillys/affiliates.html', 'https://www.tillys.com/about-tillys/affiliates.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tillys.com/about-tillys/affiliates.html', 'official_site', 'affiliate', 'Tillys'' official affiliate page states its affiliate program runs on Impact, offers a ''competitive commission up to 15%'', cross-device tracking and a product feed of 70,000+ products, for Tillys.com only. The page states no base rate and no earnings cap, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tillys.com/about-tillys/affiliates.html', 'affiliate_network', 'compensation', 'Third-party directories conflict with the brand''s ''up to 15%'' ceiling: AffJumbo reports 4%, affiliate-watch reports 5% with a 14-day cookie, and FMTC reports up to 5-15%. Because the actual base rate cannot be pinned to one figure, commission_rate is null and the conflict is documented here.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 9, 12, 8, 5, '{"compensation": "The brand publishes only an ''up to 15%'' ceiling and directories report 4-5%, so compensation is real but scored mid-range pending a verifiable base rate.", "contact_access": "A dedicated affiliate page on the official site with the Impact joining route.", "credibility": "Long-established US specialty retailer with nationwide stores and a public-company parent.", "niche_fit": "Youth surf/skate/street apparel maps well to Gen Z fashion creators on TikTok and Instagram.", "opportunity_availability": "Open application through Impact.", "ugc_evidence": "A documented network affiliate program with a large product feed; no separate ambassador program was found."}'::jsonb);
