  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/12450.', 'https://ui.awin.com/merchant-profile/12450', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'EGO Affiliate Program (Awin — US & Canada)', 'https://ui.awin.com/merchant-profile/12450', 'https://ui.awin.com/merchant-profile/12450', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/12450', 'affiliate_network', 'affiliate', 'EGO''s official Awin merchant profile (US & Canada program) is internally inconsistent: its steps text states affiliates earn 5% per sale for new customers and 3% for existing customers, while the same profile also states ''Earn 7% Commission per sale.'' Lasso separately reports a 0.8%-5.6% range with a 30-day cookie. Because the sources conflict, commission_rate is null and the conflict is documented here. No earnings-cap statement appears, so the cap is unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 7, 10, 8, 4, '{"compensation": "Rates are published but self-contradictory on the official Awin profile (3%/5% vs 7%), so no rate is recorded and compensation scores low.", "contact_access": "Joinable via the official Awin merchant profile; no direct creator contact published.", "credibility": "Established UK online fashion retailer with international shipping and network-managed programs.", "niche_fit": "Trend-led heels and going-out fashion fit fashion UGC well, especially in the UK and North America.", "opportunity_availability": "Open application through Awin for the US & Canada program.", "ugc_evidence": "An active Awin program exists; no ambassador or UGC program was found on the brand''s own pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hollister', 'https://www.hollisterco.com', 'Global teen lifestyle brand owned by Abercrombie & Fitch Co., launched in 2000 with a laid-back Southern California aesthetic across apparel, fragrance and loungewear.', 'United States', 'published') returning id into bid;
