  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.hollisterco.com/shop/us/br/Community?originalStore=eu&cmp=DIS%3ABTS24%3AHCo%3AF%3AUS%3ADG%3AIG%3AX%3ARTN%3AX%3AX%3AX%3ASTYLE-HCo%3AX%3AHollisterStyleHubSept', 'https://www.hollisterco.com/shop/us/br/Community?originalStore=eu&cmp=DIS%3ABTS24%3AHCo%3AF%3AUS%3ADG%3AIG%3AX%3ARTN%3AX%3AX%3AX%3ASTYLE-HCo%3AX%3AHollisterStyleHubSept', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://uppromote.com/affiliate-directory/hollister/.', 'https://www.hollisterco.com/shop/us/br/Community?originalStore=eu&cmp=DIS%3ABTS24%3AHCo%3AF%3AUS%3ADG%3AIG%3AX%3ARTN%3AX%3AX%3AX%3ASTYLE-HCo%3AX%3AHollisterStyleHubSept', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Hollister Style Hub — Community of Content Creators', 'https://www.hollisterco.com/shop/us/br/Community?originalStore=eu&cmp=DIS%3ABTS24%3AHCo%3AF%3AUS%3ADG%3AIG%3AX%3ARTN%3AX%3AX%3AX%3ASTYLE-HCo%3AX%3AHollisterStyleHubSept', 'https://www.hollisterco.com/shop/us/br/Community?originalStore=eu&cmp=DIS%3ABTS24%3AHCo%3AF%3AUS%3ADG%3AIG%3AX%3ARTN%3AX%3AX%3AX%3ASTYLE-HCo%3AX%3AHollisterStyleHubSept', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hollisterco.com/shop/us/br/Community?originalStore=eu&cmp=DIS%3ABTS24%3AHCo%3AF%3AUS%3ADG%3AIG%3AX%3ARTN%3AX%3AX%3AX%3ASTYLE-HCo%3AX%3AHollisterStyleHubSept', 'official_site', 'ugc_collab', 'Hollister''s official Community page introduces the Hollister Style Hub, its community of content creators: members receive gifted products, unlock levels by completing challenges, earn commission, and can be featured in campaigns. Eligibility as published: loves Hollister, creates content, has more than 1,500 followers on TikTok or Instagram, and is 16 or older.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://community.hollisterco.com/account/terms', 'official_site', 'general', 'The official Hollister Style Hub terms describe a level-based creator community hosted on the Duel platform where higher levels bring gifted product and higher commission rates, plus a Hollister Storefront program for earning commission on curated UGC; applicants must be invited and accepted to participate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/hollister/', 'affiliate_network', 'affiliate', 'Uppromote''s affiliate directory reports Hollister''s network affiliate program runs primarily through Impact with a 10-day cookie and commission of 3-5% per sale, varying by performance and region.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/hollisterco-com-affiliate-program', 'listing', 'compensation', 'Shopper''s partnership listing reports a Hollister payout of 5-10% per sale, which conflicts with the 3-5% range reported by Uppromote, and neither the Style Hub pages nor the terms publish a rate. commission_rate is therefore null with the conflict documented. No earnings-cap statement was found, so the cap is unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 8, 12, 7, 5, '{"compensation": "Commission is confirmed by the brand''s own pages and terms, but no rate is published and directories conflict (3-5% vs 5-10%), so no rate is recorded and compensation scores conservatively.", "contact_access": "A public creator community page on the official site spells out eligibility and benefits.", "credibility": "A flagship brand of Abercrombie & Fitch Co., a major publicly traded US retailer.", "niche_fit": "Teen/Gen Z apparel from a major youth brand \u2014 a core fashion UGC category with a clear TikTok/Instagram audience.", "opportunity_availability": "Open to creators with 1,500+ TikTok/Instagram followers, but the terms state applicants must be invited and accepted, so availability is not fully open.", "ugc_evidence": "A formal, level-based creator community (Style Hub) with gifting, challenges, commission and campaign features, plus a UGC Storefront program \u2014 strong, current creator infrastructure."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Thunder Honey', 'https://thunderhoney.co', 'Swedish functional drink brand designed in Stockholm. Its product Daylight is a cacao-based drink mix with 11 dosed actives — dual-extracted lion''s mane, cordyceps and chaga mushrooms, nicotinamide riboside (an NAD+ precursor), CDP-choline, L-theanine, rhodiola, MCT, 3 g collagen peptides and bee propolis — with no added caffeine, sold by subscription and one-time purchase, shipping across Sweden and the EU.', 'Sweden', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'hello@thunderhoney.co', 'https://thunderhoney.co/affiliate', 'https://thunderhoney.co/affiliate', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'support@thunderhoney.co', null, 'https://thunderhoney.co/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://thunderhoney.co/affiliate.', 'https://thunderhoney.co/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Thunder Honey Affiliate Program (Shopify Collabs)', 'https://thunderhoney.co/affiliate', 'https://thunderhoney.co/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thunderhoney.co/affiliate', 'official_site', 'affiliate', 'Thunder Honey''s own affiliate page states affiliates earn on each order placed with their code with ''No caps'', and its FAQ answers ''How much can I earn?'' with ''There is no cap'' — verified uncapped. The page routes applications through Shopify Collabs and, while that setup is finished, invites applications to hello@thunderhoney.co; no percentage rate is published (rate is confirmed at approval), and affiliates also earn on recurring subscription orders.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thunderhoney.co/', 'official_site', 'general', 'Official homepage: ''Functional cacao. Developed in Sweden'', designed in Stockholm, ships from Sweden with prices in SEK; 11 actives at named doses in a 12 g scoop, third-party tested by Eurofins, 2 years and 28 formulations in development, 70,000+ servings poured, 30-day money-back guarantee, and 1% of every order to bee conservation. Founders named as Joakim Bjarke and Nina Strauss.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 16, 12, 9, 4, '{"compensation": "Verified uncapped earnings on the brand''s own page, including recurring subscription orders; the percentage itself is only confirmed at approval, which keeps this below the top band.", "contact_access": "Public affiliate page plus two published emails (hello@ for applications, support@ for general contact).", "credibility": "Young Swedish brand with third-party Eurofins testing, transparent full-dose labelling and 70,000+ servings sold, but limited track record.", "niche_fit": "Functional morning-drink ritual with strong before/after coffee-swap storytelling \u2014 a proven wellness UGC format.", "opportunity_availability": "Open application route via Shopify Collabs, with an email application route published while the Collabs setup is finished.", "ugc_evidence": "The brand runs a public affiliate program and features customer video/review content on its homepage, but publishes no structured creator program details beyond the affiliate page."}'::jsonb);
