  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mixhers Affiliate Program', 'https://mixhers.com/pages/affiliate', 'https://mixhers.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mixhers.com/pages/affiliate', 'official_site', 'affiliate', 'Mixhers'' own affiliate page FAQ states: ''You earn a cash commission on every order placed through your link, with no cap'' — verified uncapped. The program is powered by Social Snowball (apply at mixhers.socialsnowball.io), is free to join with no follower minimum, pays cash (not store credit) monthly, and publishes no percentage on the page itself.', 'verified', now());
