  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mixhers.com/pages/affiliate', 'listing', 'general', 'Brand figures published on Mixhers'' own affiliate page: 17K+ five-star reviews, 7M+ sticks sold, 300 MDs & OB/GYNs surveyed, 169K women in its community.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 15, 11, 9, 4, '{"compensation": "Verified uncapped cash commission; the 10% rate comes from the FlexOffers listing rather than the brand''s own page, which publishes no percentage.", "contact_access": "Public affiliate page with a direct Social Snowball application link; no published partnerships email.", "credibility": "Established 2019 brand with 17K+ five-star reviews and 7M+ sticks sold.", "niche_fit": "Women''s hormone-health drink mixes built for TikTok/Instagram creator content \u2014 squarely in the wellness UGC niche.", "opportunity_availability": "Free to join with no follower minimum, per the brand''s own page.", "ugc_evidence": "Large stated community (169K women) and a creator-facing affiliate program with cash payouts promoted on the brand''s own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Yu Tea', 'https://yutea.com', 'US family-run tea company started in rural Oregon in 2004, selling certified-organic Japanese whole-leaf green teas stone-milled into fine powders — matcha, sencha, hojicha, genmaicha and decaf versions — sourced from organic farms in Japan, so drinkers consume the whole leaf rather than an infusion.', 'United States', 'published') returning id into bid;
