  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Yu Tea Affiliate Program', 'https://affiliates.yutea.com/', 'https://affiliates.yutea.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliates.yutea.com/', 'official_site', 'affiliate', 'Yu Tea''s own affiliate portal FAQ answers ''Is there a limit to how much I can earn?'' with ''Not at all! The more you share, the more you earn. There''s no cap on commissions'' — verified uncapped. Terms on the portal: 60-day cookie, payouts at the start of the month once the balance exceeds $25, via PayPal, bank transfer or store credit; the page describes the rate only as ''attractive commissions'', so no percentage is recorded.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yutea.com/', 'official_site', 'general', 'Official homepage: Yu Tea started as a small family venture in rural Oregon in 2004; teas are stone-milled whole-leaf powders from certified organic farms in Japan; the footer publishes hello@yutea.com and the brand''s Facebook, Instagram, TikTok and X URLs.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 15, 11, 9, 4, '{"compensation": "Verified uncapped earnings with a 60-day cookie and cash payout options; no percentage is published, which caps this below the top band.", "contact_access": "Public affiliate portal plus a published general email and four social profiles on the official homepage.", "credibility": "Family business operating since 2004 with certified-organic sourcing and published batch testing for caffeine/catechin content.", "niche_fit": "Matcha and whole-leaf green tea powders ride a strong creator trend (matcha routines, taste tests), though the brand itself is quiet and traditional.", "opportunity_availability": "Self-serve affiliate portal open to applicants.", "ugc_evidence": "An open affiliate portal exists, but there is little public evidence of structured creator campaigns beyond it."}'::jsonb);
