  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partners.thefresh20.com/referrals-1', 'official_site', 'affiliate', 'The Fresh 20''s own partner page states: ''For each sale of a paid subscription, you''ll receive a 15% commission, paid out monthly with no cap on your earning potential!'' and repeats ''No cap on commissions!'' — verified uncapped at a 15% rate. The program is open to everyone with no following required.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partners.thefresh20.com/referrals-1', 'official_site', 'compensation', 'The same page carries ''Earn up to 20%'' headlines and one visibly unfinished section containing ''(CONFIRM)'' draft markers (that draft section mentions monthly PayPal payouts over $50 and an exclusive 10% audience discount). The 15% figure is the one stated as the operative term three times; the draft fragments should be confirmed with the brand.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 9, 16, 10, 9, 3, '{"compensation": "15% commission with verified uncapped earning potential stated on the brand''s own page; payout mechanics are partly in an unfinished draft section.", "contact_access": "Public partner signup page; no published partnerships email found.", "credibility": "Long-running meal-planning service, but its partner page still contains unfinished draft copy, which dents polish.", "niche_fit": "Meal planning and weeknight-cooking content is a steady food-creator niche; a subscription service is less visual than a physical product.", "opportunity_availability": "Open to everyone, no following required, per the brand''s own page.", "ugc_evidence": "A public partner program exists, but there is little visible creator-content evidence around the brand."}'::jsonb);
