  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.eset.com/us/business/partner/online-affiliates.', 'https://www.eset.com/us/business/partner/online-affiliates', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.eset.com/us/business/partner/online-affiliates', 'listing', 'affiliate', 'ESET''s online-affiliates program is listed across multiple affiliate directories (getlasso, affpaying, openaffiliate.dev, Sovrn) with consistent terms: 20% recurring commission on CJ Affiliate, paid on new purchases AND renewals, 45-day cookie, $50 payout threshold, manual approval. The brand''s own program page is eset.com/us/business/partner/online-affiliates. No earnings-cap statement is published, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 17, 7, 7, 5, '{"niche_fit": "Consumer antivirus is a proven tech-creator niche; ESET''s lightweight products demo well on older hardware.", "ugc_evidence": "Program is marketed to publishers through CJ; no dedicated creator page was found on the brand''s own site.", "compensation": "20% recurring, and unusually it pays on renewals as well as new purchases, which compounds creator earnings; no cap statement published, so cap stays unknown.", "contact_access": "Contact runs through the CJ program and the brand''s partner pages; no public partnerships email was seen.", "opportunity_availability": "Application through CJ Affiliate with manual approval and a $50 payout threshold.", "credibility": "One of the oldest independent antivirus vendors, headquartered in Bratislava and selling in 200+ countries."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Norton', 'https://www.norton.com', 'US consumer cyber-safety brand from Gen Digital selling antivirus, VPN and identity-protection subscriptions (Norton 360, Norton VPN, LifeLock) direct to consumers.', 'United States', 'published') returning id into bid;
