  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://app.impact.com', 'affiliate_network', 'affiliate', 'Norton''s affiliate presence runs through Impact (also CJ and regional networks). Published rates CONFLICT: baseline listings report about 20% (LinkClicky, getlasso), some networks report 25% (Affilorama), and the Impact ''Norton VPN Creator'' campaign page itself states a 50% payout with a 60-day referral period. Because the sources conflict, commission_rate is recorded as null with the conflict documented here. No earnings-cap statement is published, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 10, 7, 8, 5, '{"niche_fit": "Norton is one of the most recognised consumer security brands, an easy fit for mainstream tech and family-safety creators.", "ugc_evidence": "Impact runs a dedicated ''Norton VPN Creator'' campaign, a direct signal the brand recruits creators, not just coupon sites.", "compensation": "Rate could not be settled: published figures conflict (about 20% baseline, 25% on some networks, 50% on the Impact creator campaign), so the rate is recorded as null rather than guessed; cap unknown.", "contact_access": "Contact runs through the network programs; no public partnerships email was seen on the pages reviewed.", "opportunity_availability": "Open application through Impact and CJ.", "credibility": "Flagship consumer brand of Gen Digital, among the largest cyber-safety companies in the world."}'::jsonb);
