  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://macpaw.com/affiliate', 'official_program_page', 'affiliate', 'MacPaw''s own affiliate page (macpaw.com/affiliate, corroborated by openaffiliate.dev and clickaffiliate.net, checked Oct 2026) describes an Impact program paying a 35% starting commission per sale with performance tiers above that, a 180-day cookie, monthly payouts and manual review. The page''s ''sky''s the limit'' wording is vague marketing, NOT an explicit no-cap statement, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 18, 8, 7, 4, '{"niche_fit": "CleanMyMac and the Mac utility suite are natural, demonstrable products for Apple-focused creators.", "ugc_evidence": "The brand maintains its own affiliate landing page aimed at promoters and reviewers, with creator-friendly assets via Impact.", "compensation": "35% starting commission with performance tiers above it and an unusually long 180-day cookie; ''sky''s the limit'' is not an explicit no-cap statement, so cap stays unknown.", "contact_access": "Program page and Impact dashboard provide the contact route; no public partnerships email was seen.", "opportunity_availability": "Application through Impact with manual review.", "credibility": "Well-known Mac software house; scored one point lower because its catalogue is Apple-only."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Descript', 'https://www.descript.com', 'US software company selling an AI-powered audio and video editor used by creators and podcasters, with text-based editing, screen recording and AI voice tools.', 'United States', 'published') returning id into bid;
