  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.descript.com/affiliate-terms', 'official_program_page', 'affiliate', 'Descript''s own affiliate terms (fetched in full) pay a FLAT $25 one-time bounty per new qualifying subscription (Creator/Pro plans, monthly or annual; new customers only; no renewals), with a 30-day purchase window, so commission_rate is null and the flat bounty is recorded here. The same terms CAP total annual commissions at $100,000 per affiliate, so the program is explicitly capped, not uncapped; the cap field records ''unknown'' per directory convention with the $100k cap documented here. Program page: descript.com/affiliate, run on PartnerStack.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 12, 8, 8, 4, '{"niche_fit": "Descript is a tool creators themselves use daily, so it fits creator-audience content almost perfectly.", "ugc_evidence": "The affiliate program is aimed squarely at creators and podcasters who demo the editor in their own workflows.", "compensation": "Flat $25 one-time bounty per new qualifying subscription, no renewals, and the terms cap annual commissions at $100,000 per affiliate, so earnings are bounded; rate recorded as null because it is a flat bounty.", "contact_access": "Full public terms and a program page on the brand''s own domain; no public partnerships email was seen.", "opportunity_availability": "Open application through PartnerStack from the brand''s program page.", "credibility": "Established, venture-backed creator-tools company with a large user base."}'::jsonb);
