  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.awin.com/us/news-and-events/program-news/new-affiliate-program-hamilton-beach', 'affiliate_network', 'affiliate', 'Awin''s own program announcement (fetched) states the Hamilton Beach program pays 6% commission (a portion of revenue) on completed sales within a 45-day cookie window, with in-house account management, and warns that not all applications are accepted. FlexOffers lists 5%; Awin''s own announcement governs. No earnings-cap statement is published, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 7, 6, 5, '{"niche_fit": "Everyday kitchen appliances are highly demonstrable home and food-creator content.", "ugc_evidence": "The Awin announcement targets quality content publishers; no separate creator page was found.", "compensation": "6% of revenue is modest but the brand''s low price points convert in volume; 45-day cookie; no cap statement published, so cap stays unknown.", "contact_access": "Awin''s announcement names program contacts at the network; no public brand partnerships email was seen.", "opportunity_availability": "Application through Awin, but the announcement says applications are selective and not all are accepted.", "credibility": "The #1 selling brand of small kitchen appliances in the US, per the program''s own description."}'::jsonb);
