  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/keurig/', 'listing', 'affiliate', 'Lasso''s Keurig program listing (fetched) states 8% per sale with a short 10-day cookie, and its join link routes to FlexOffers (publisherpro.flexoffers.com). Other published sources conflict, quoting figures from about 1% (Rakuten) to 2-4% and category-split rates, and some name Impact instead. Because the rate and network reports conflict, commission_rate is recorded as null and FlexOffers is recorded from the listing''s actual join link. No earnings-cap statement is published, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 8, 6, 7, 5, '{"niche_fit": "Coffee brewers and pods are everyday, highly demonstrable home products with a built-in repeat-purchase story.", "ugc_evidence": "The program is promoted to coffee bloggers and reviewers through network listings; no dedicated creator page was found.", "compensation": "Published rates conflict (about 1% to 8% depending on source and network) and the cookie is only 10 days, so the rate is recorded as null rather than guessed; cap unknown.", "contact_access": "Contact runs through the networks; no public partnerships email was seen on the pages fetched.", "opportunity_availability": "Open application through FlexOffers and other networks carrying the program.", "credibility": "The dominant single-serve coffee brand in the US, owned by Keurig Dr Pepper."}'::jsonb);
