  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliate.pawfit.com/', 'official_program_page', 'affiliate', 'Pawfit runs its own Affiliate Programme at affiliate.pawfit.com: affiliates receive a unique discount code (customers save up to 10%) and earn up to 20% commission, paid quarterly after a 30-day cooling-off period; the program is open to influencers, retailers and businesses. Its terms (pawfit.com/en-us/legal_affiliate.html) limit commissionable items to the Pawfit 3 and Pawfit Lite trackers. ''Up to 20%'' is a rate ceiling, not an uncapped statement; no earnings-cap statement is published, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 14, 7, 8, 3, '{"niche_fit": "GPS trackers are demonstrable pet-tech with strong lost-pet storytelling for pet creators.", "ugc_evidence": "The programme explicitly welcomes influencers and gives them customer discount codes to share in content.", "compensation": "Up to 20% commission (a ceiling) on tracker sales, paid quarterly after a 30-day cooling-off period; no cap statement published, so cap stays unknown.", "contact_access": "Dedicated affiliate portal on the brand''s own subdomain; no public partnerships email was seen.", "opportunity_availability": "Open signup at the brand''s own affiliate portal for influencers, retailers and businesses.", "credibility": "Smaller UK pet-tech brand; scored lower because the range is two trackers plus a subscription."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PawSafe', 'https://pawsafe.com', 'US pet-products brand designing everyday pet-care products (including its dog seat belt and other safety and care items) sold direct to consumers from Wilmington, Delaware.', 'United States', 'published') returning id into bid;
