  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GoAffPro', 30, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://pawsafe.com/en-se/pages/pet-affiliate-program.', 'https://pawsafe.com/en-se/pages/pet-affiliate-program', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pawsafe.com/en-se/pages/pet-affiliate-program', 'official_program_page', 'affiliate', 'PawSafe''s own affiliate program page (fetched) states affiliates sign up via GoAffPro, are approved within 1-2 business days, and earn 30% of revenue on every referred sale; the page welcomes blogs, social media, websites and email lists (coupon-finder sites excluded). No earnings-cap statement is published, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 17, 6, 8, 3, '{"niche_fit": "Pet safety and care products are everyday, demonstrable items for dog-focused creators.", "ugc_evidence": "The brand''s own page explicitly recruits social-media and video creators, not just bloggers, and supplies a custom link per affiliate.", "compensation": "30% of revenue on every referred sale is one of the stronger pet rates found; no cap statement published, so cap stays unknown.", "contact_access": "Signup and management run through the GoAffPro portal linked from the brand''s page; no public partnerships email was seen (a postal address in Wilmington, Delaware is published).", "opportunity_availability": "Open application with approval in 1-2 business days per the brand''s own page.", "credibility": "Smaller DTC pet brand; scored lower on limited public track record compared with national pet retailers."}'::jsonb);
